<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref } from 'vue'
import { cnyToMicro,money } from '../format'
import { createPaymentJournal } from '../payments-journal'
import { createPaymentEpoch,newPaymentPending,paymentPageCursor,paymentPollDelay,resumePaymentReview } from '../payments-state'
import { PaymentError,paymentIdentityFailure,paymentRequest,paymentUnknownWrite } from '../payments-transport'
import { parsePaymentCapabilities,parsePaymentInput,parsePaymentObservation,parsePaymentOrder,parsePaymentPage,parsePaymentPolicy,parsePaymentReceipt,parsePaymentSingle,parsePaymentSKU,parsePaymentSKUVersion,parsePaymentWrite,paymentID,paymentLabels,paymentOperationPath } from '../payments'
import type { PaymentCapabilities,PaymentInput,PaymentKind,PaymentObservation,PaymentOrder,PaymentPending,PaymentPolicy,PaymentReceipt,PaymentSKU,PaymentSKUVersion } from '../payments'
import type { PaymentReview,PaymentTicket } from '../payments-state'
const props=defineProps<{platform:boolean;actor:string;tenant:string;csrf:string;context:string;admin:boolean;owner:boolean}>(),emit=defineEmits<{'identity-check':[]}>()
const gate=createPaymentEpoch(),journal=createPaymentJournal();gate.auth(props.context)
const scope=props.platform?'platform':props.tenant,prefix=props.platform?'/api/platform':'/api/wallet'
const capabilities=ref<PaymentCapabilities|null>(null),skus=ref<PaymentSKU[]>([]),sale=ref<PaymentSKUVersion[]>([]),orders=ref<PaymentOrder[]>([]),selected=ref<PaymentOrder|null>(null),observations=ref<PaymentObservation[]>([]),policy=ref<PaymentPolicy|null>(null)
const pending=ref<PaymentPending[]>([]),reviews=ref<Record<string,PaymentReview>>({}),error=ref(''),storageError=ref(''),notice=ref(''),identityBlocked=ref(false),storageReady=ref(false),saving=ref(false),inspectBusy=ref(false),busy=ref<Record<string,boolean>>({})
const cursor=ref<Record<string,string|null>>({skus:null,orders:null,observations:null}),seen:Record<string,string[]>={skus:[],orders:[],observations:[]}
const latestReceipt=ref<PaymentReceipt|null>(null)
const logicalOrder=ref(''),publishOpen=ref(false),activateOpen=ref(false),formError=ref('')
const publishForm=ref({sku:'',revision:'0',name:'',amount:''}),activateForm=ref({sku:'',revision:'1',version:'',enabled:false})
const policyEnabled=ref(false),policyStage=ref<'loading'|'editing'|'submitting'|'unknown'>('loading'),policyReadReady=ref(false),policyUnknown=ref(false)
let disposed=false,pollTimer:ReturnType<typeof setTimeout>|undefined,pollAttempt=0,pollFocus='',unsubscribe=()=>{}
const writable=computed(()=>!identityBlocked.value&&storageReady.value&&!storageError.value&&!saving.value&&(props.platform?props.admin:props.owner))
const versionRows=computed(()=>props.platform?skus.value.map(s=>({sku:s,version:s.current_version})):sale.value.map(v=>({sku:null,version:v})))
const text=(cause:unknown)=>cause instanceof Error?cause.message:'操作未完成，请保留原编号核查。'
const label=(state:string)=>paymentLabels[state]||'状态不可识别'
const blocked=(kind:PaymentKind,target:string)=>pending.value.some(p=>p.kind===kind&&p.target_id===target)
function invalidate(){identityBlocked.value=true;stopPoll();gate.dispose();clearSnapshots();pending.value=[];reviews.value={}}
defineExpose({invalidate})
function clearSnapshots(){capabilities.value=null;skus.value=[];sale.value=[];orders.value=[];selected.value=null;observations.value=[];policy.value=null;latestReceipt.value=null;publishOpen.value=false;activateOpen.value=false}
function identityFailure(cause:unknown){if(!paymentIdentityFailure(cause))return;identityBlocked.value=true;stopPoll();gate.auth(`${props.context}:blocked`);clearSnapshots();pending.value=[];reviews.value={};if(cause instanceof PaymentError&&cause.code==='reauth_required')window.dispatchEvent(new CustomEvent('moni:reauth'));if(cause instanceof PaymentError&&cause.status===401)window.dispatchEvent(new CustomEvent('moni:unauthenticated'));emit('identity-check')}
function deadline(ticket:PaymentTicket,callback:()=>void){if(gate.expire(ticket)){callback();error.value='等待超时；旧响应已作废，已提交操作保留原编号核查。'}}
async function restore(){const ticket=gate.ticket('journal');try{const rows=await journal.list(props.actor,scope,ticket.signal);if(!gate.accepts(ticket))return;pending.value=rows;storageReady.value=true;storageError.value='';for(const p of rows)if(!reviews.value[p.operation_id])reviews.value[p.operation_id]=resumePaymentReview(p);if(!pollFocus&&rows.length){pollFocus=rows[0]!.operation_id;pollAttempt=0;schedulePoll()}}catch(cause){if(gate.accepts(ticket)){storageReady.value=false;storageError.value=text(cause)}}}
async function loadCapabilities(){const ticket=gate.ticket('capabilities');try{const value=await paymentRequest(`${prefix}/payment-capabilities`,{signal:ticket.signal,decode:v=>parsePaymentSingle(v,parsePaymentCapabilities),onDeadline:()=>deadline(ticket,()=>{capabilities.value=null})});if(gate.accepts(ticket))capabilities.value=value}catch(cause){if(gate.accepts(ticket)){capabilities.value=null;error.value=text(cause);identityFailure(cause)}}}
async function loadList(kind:'skus'|'orders'|'observations',next=false){if(identityBlocked.value)return;let order='';try{if(kind==='observations')order=paymentID(logicalOrder.value)}catch{error.value='请输入规范逻辑订单 UUID 后查看安全观察。';return}const ticket=gate.ticket(kind),at=next?cursor.value[kind]:null;if(next&&!at)return;busy.value[kind]=true;error.value='';if(!next)seen[kind]=[]
 try{const path=kind==='observations'?`${prefix}/payment-orders/${order}/observations`:`${prefix}/payment-${kind}`;const value=await paymentRequest(`${path}${at?`?cursor=${encodeURIComponent(at)}`:''}`,{signal:ticket.signal,decode:v=>kind==='orders'?parsePaymentPage(v,x=>parsePaymentOrder(x,props.platform?undefined:props.tenant)):kind==='observations'?parsePaymentPage(v,x=>parsePaymentObservation(x,order)):props.platform?parsePaymentPage(v,x=>parsePaymentSKU(x)):parsePaymentPage(v,parsePaymentSKUVersion),onDeadline:()=>deadline(ticket,()=>{busy.value[kind]=false;if(kind==='orders')orders.value=[];else if(kind==='observations')observations.value=[];else{skus.value=[];sale.value=[]}})});if(!gate.accepts(ticket))return;cursor.value[kind]=paymentPageCursor(value.next_cursor,at,seen[kind]!);if(at)seen[kind]!.push(at);if(kind==='orders')orders.value=value.data as PaymentOrder[];else if(kind==='observations')observations.value=value.data as PaymentObservation[];else if(props.platform)skus.value=value.data as PaymentSKU[];else sale.value=value.data as PaymentSKUVersion[]
 }catch(cause){if(gate.accepts(ticket)){error.value=text(cause);identityFailure(cause)}}finally{if(gate.accepts(ticket))busy.value[kind]=false}}
async function getOrder(id:string){const ticket=gate.ticket('order');selected.value=null;try{const order=paymentID(id),value=await paymentRequest(`${prefix}/payment-orders/${order}`,{signal:ticket.signal,decode:v=>parsePaymentSingle(v,x=>parsePaymentOrder(x,props.platform?undefined:props.tenant,order)),onDeadline:()=>deadline(ticket,()=>{selected.value=null})});if(gate.accepts(ticket)){selected.value=value;logicalOrder.value=value.id}}catch(cause){if(gate.accepts(ticket)){error.value=text(cause);identityFailure(cause)}}}
async function loadPolicy(){if(!props.platform||!props.admin||identityBlocked.value)return;const ticket=gate.ticket('policy-read');policyReadReady.value=false;try{const value=await paymentRequest('/api/platform/payment-policy',{signal:ticket.signal,decode:v=>parsePaymentSingle(v,parsePaymentPolicy),onDeadline:()=>deadline(ticket,()=>{policy.value=null;policyReadReady.value=false})});if(!gate.accepts(ticket))return;policy.value=value;policyReadReady.value=true;if(policyStage.value==='loading'){policyStage.value='editing';policyEnabled.value=value.enabled}}catch(cause){if(gate.accepts(ticket)){policy.value=null;error.value=text(cause);identityFailure(cause)}}}
async function cleanup(p:PaymentPending,ticket:PaymentTicket){if(!gate.accepts(ticket))return;try{const removed=await journal.finish(props.actor,p,ticket.signal);if(!gate.accepts(ticket))return;if(!removed){storageError.value='该目标已有不同的原操作编号，晚回结果不能删除它。';return}pending.value=pending.value.filter(row=>row.operation_id!==p.operation_id);if(reviews.value[p.operation_id])reviews.value[p.operation_id]!.cleanupBlocked=false;storageError.value='';if(pollFocus===p.operation_id)stopPoll()}catch(cause){if(gate.accepts(ticket))storageError.value=`原结果已有明确响应，但标识尚未可靠清理，仍阻断该目标新写。${text(cause)}`}}
async function retryCleanup(p:PaymentPending){const review=reviews.value[p.operation_id];if(identityBlocked.value||!review||!['settled','known_failure'].includes(review.phase))return;const ticket=gate.ticket('cleanup');await cleanup(p,ticket)}
async function terminal(receipt:PaymentReceipt,p:PaymentPending,ticket:PaymentTicket){if(!gate.accepts(ticket))return;reviews.value[p.operation_id]={phase:'settled',pending:p,receipt,cleanupBlocked:true};latestReceipt.value=receipt;notice.value=`${label(receipt.kind)}：${receipt.status==='accepted'?'原操作已接受':'原操作明确拒绝'}${receipt.status==='rejected'?`（${label(receipt.reason)}）`:''}。`;await cleanup(p,ticket);if(gate.accepts(ticket)){void loadList('orders');if(props.platform)void loadList('skus')}}
async function perform(kind:PaymentKind,target:string,input:Record<string,unknown>){if(!writable.value)return;if(!props.csrf){error.value='当前会话校验信息缺失，请刷新身份。';return}let created:PaymentPending;try{created=newPaymentPending(kind,scope,paymentID(target));parsePaymentInput(kind,{...input,operation_id:created.operation_id})}catch(cause){error.value=text(cause);return}const ticket=gate.ticket('mutation');saving.value=true;error.value='';let p:PaymentPending|undefined
 try{const admission=await journal.begin(props.actor,created,ticket.signal);if(!gate.accepts(ticket))return;p=admission.pending;if(!pending.value.some(row=>row.operation_id===p!.operation_id))pending.value.unshift(p);if(!admission.inserted){reviews.value[p.operation_id]=resumePaymentReview(p);notice.value='已恢复该目标原编号，没有发送新命令。';pollFocus=p.operation_id;pollAttempt=0;schedulePoll();return}
  reviews.value[p.operation_id]={phase:'submitting',pending:p,receipt:null,cleanupBlocked:true};publishOpen.value=false;activateOpen.value=false
  const path=kind==='payment.sku.publish'?'/api/platform/payment-skus':kind==='payment.sku.activate'?`/api/platform/payment-skus/${target}/active`:kind==='payment.order.create'?'/api/wallet/payment-orders':`/api/wallet/payment-orders/${target}/cancel`
  const original=p;const result=await paymentRequest(path,{method:kind==='payment.sku.activate'?'PUT':'POST',body:{...input,operation_id:p.operation_id} as PaymentInput,csrf:props.csrf,signal:ticket.signal,decode:v=>parsePaymentWrite(v,original,props.actor),onDeadline:()=>deadline(ticket,()=>{reviews.value[original.operation_id]=resumePaymentReview(original);saving.value=false;selected.value=null;pollFocus=original.operation_id;pollAttempt=0;schedulePoll()})});if(!gate.accepts(ticket))return;if(result.order)selected.value=result.order;await terminal(result.receipt,p,ticket)
 }catch(cause){if(!gate.accepts(ticket))return;error.value=text(cause);if(p){reviews.value[p.operation_id]={phase:paymentUnknownWrite(cause)?'unknown':'known_failure',pending:p,receipt:null,cleanupBlocked:true};if(paymentUnknownWrite(cause)){pollFocus=p.operation_id;pollAttempt=0;schedulePoll()}else await cleanup(p,ticket)}else{storageReady.value=false;storageError.value=text(cause)}identityFailure(cause)
 }finally{if(gate.accepts(ticket))saving.value=false}}
function stopPoll(){if(pollTimer!==undefined)clearTimeout(pollTimer);pollTimer=undefined}
const available=()=>!disposed&&!identityBlocked.value&&document.visibilityState==='visible'&&navigator.onLine
function schedulePoll(){stopPoll();const delay=paymentPollDelay(pollAttempt);if(delay===null||!available()||inspectBusy.value||!pending.value.some(p=>p.operation_id===pollFocus))return;pollTimer=setTimeout(()=>{pollTimer=undefined;const p=pending.value.find(p=>p.operation_id===pollFocus);if(p){pollAttempt++;void inspect(p)}},delay)}
async function inspect(p:PaymentPending,manual=false){if(!available()||inspectBusy.value)return;if(manual){pollFocus=p.operation_id;pollAttempt=0}stopPoll();const ticket=gate.ticket('receipt');inspectBusy.value=true
 try{const result=await paymentRequest(paymentOperationPath(p),{signal:ticket.signal,decode:v=>parsePaymentSingle(v,x=>parsePaymentReceipt(x,p,props.actor)),onDeadline:()=>deadline(ticket,()=>{inspectBusy.value=false;schedulePoll()})});if(gate.accepts(ticket))await terminal(result,p,ticket)}catch(cause){if(gate.accepts(ticket)){error.value=text(cause);identityFailure(cause)}}finally{if(gate.accepts(ticket)){inspectBusy.value=false;schedulePoll()}}}
function newPolicyIntent(){if(policyReadReady.value&&policy.value&&policyStage.value!=='submitting'){policyStage.value='editing';policyEnabled.value=policy.value.enabled}}
async function savePolicy(){if(!props.admin||identityBlocked.value||!policy.value||policyStage.value!=='editing')return;const ticket=gate.ticket('policy-write'),revision=policy.value.revision;policyStage.value='submitting';policyReadReady.value=false
 try{const value=await paymentRequest('/api/platform/payment-policy',{method:'PUT',body:{expected_revision:revision,enabled:policyEnabled.value},csrf:props.csrf,signal:ticket.signal,decode:v=>parsePaymentSingle(v,parsePaymentPolicy),onDeadline:()=>deadline(ticket,()=>{policyUnknown.value=true;policyStage.value='unknown';void loadPolicy()})});if(gate.accepts(ticket)){policy.value=value;policyEnabled.value=value.enabled;policyStage.value='editing';policyReadReady.value=true;void loadCapabilities()}}
 catch(cause){if(gate.accepts(ticket)){policyStage.value='unknown';if(!(cause instanceof PaymentError&&cause.code==='payment_policy_conflict')&&paymentUnknownWrite(cause))policyUnknown.value=true;error.value=text(cause);identityFailure(cause);void loadPolicy()}}}
function openPublish(sku?:PaymentSKU){formError.value='';const v=sku?.current_version;publishForm.value={sku:sku?.id||crypto.randomUUID(),revision:sku?.revision||'0',name:v?.display_name||'',amount:v?`${BigInt(v.amount)/1000000n}.${(BigInt(v.amount)%1000000n).toString().padStart(6,'0')}`:''};publishOpen.value=true}
function publish(){try{const amount=cnyToMicro(publishForm.value.amount);if(amount==='0')throw new Error('模拟充值金额必须大于零。');if(!publishForm.value.name.trim())throw new Error('请输入商品名称。');void perform('payment.sku.publish',publishForm.value.sku,{sku_id:publishForm.value.sku,expected_revision:publishForm.value.revision,display_name:publishForm.value.name,amount})}catch(cause){formError.value=text(cause)}}
function openActivate(s:PaymentSKU){activateForm.value={sku:s.id,revision:s.revision,version:s.current_version_id||'',enabled:s.enabled};formError.value='';activateOpen.value=true}
function activate(){try{const version=activateForm.value.version?paymentID(activateForm.value.version):null;if(activateForm.value.enabled&&!version)throw new Error('启用商品须指定已发布的版本编号。');void perform('payment.sku.activate',activateForm.value.sku,{expected_revision:activateForm.value.revision,version_id:version,enabled:activateForm.value.enabled})}catch(cause){formError.value=text(cause)}}
function availability(){if(!available()){stopPoll();gate.cancel('receipt');inspectBusy.value=false}else schedulePoll()}
function refresh(){error.value='';void loadCapabilities();void loadList('skus');void loadList('orders');void loadPolicy()}
onMounted(()=>{void restore();refresh();unsubscribe=journal.subscribe(()=>{if(!disposed&&!identityBlocked.value)void restore()});document.addEventListener('visibilitychange',availability);window.addEventListener('online',availability);window.addEventListener('offline',availability)})
onBeforeUnmount(()=>{disposed=true;stopPoll();gate.dispose();journal.close();unsubscribe();document.removeEventListener('visibilitychange',availability);window.removeEventListener('online',availability);window.removeEventListener('offline',availability);clearSnapshots();pending.value=[];reviews.value={}})
</script>
<template>
 <div class="payments-panel">
  <el-alert title="本地模拟，无真实收款" description="此处订单与模拟钱包到账用于本地联调，不产生真实付款或结算。取消或过期不否认原窗口内的合法捕获。" type="warning" :closable="false" show-icon />
  <div class="payments-toolbar"><span v-if="capabilities">{{ label(capabilities.mode) }} · {{ capabilities.payments_enabled?'可创建模拟订单':'新售暂不可用' }}</span><el-button @click="refresh">刷新当前状态</el-button></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false" /><el-alert v-if="storageError" :title="storageError" type="error" :closable="false" /><el-alert v-if="notice" :title="notice" type="info" :closable="false" />
  <el-alert v-if="identityBlocked" title="当前身份需要重新确认，已停止读取和提交；原操作编号仍保留在浏览器中。" type="warning" :closable="false" />
  <section v-if="latestReceipt" class="panel payments-section"><div class="panel-header"><div class="panel-title">已确认原操作回执</div></div><dl class="detail-list panel-body"><dt>操作</dt><dd>{{ label(latestReceipt.kind) }} · {{ latestReceipt.status==='accepted'?'已接受':'已拒绝' }}</dd><dt>原编号</dt><dd class="mono">{{ latestReceipt.operation_id }}</dd><dt>结果资源编号</dt><dd class="mono">{{ latestReceipt.resource_id||'无资源，未应用' }}</dd><dt>结果时刻</dt><dd>{{ latestReceipt.created_at }}</dd></dl><p v-if="latestReceipt.kind==='payment.sku.publish'&&latestReceipt.status==='accepted'" class="panel-body field-hint">结果资源编号是新发布版本，可复制到“版本与上下架”中设为当前版本；此回执不代表商品已上架。</p></section>
  <section v-if="pending.length" class="panel payments-section"><div class="panel-header"><div><div class="panel-title">原操作待核查</div><div class="panel-subtitle">先保存原编号，再提交；404、离线或等待很久都不能证明原操作失败。</div></div></div><div class="panel-body"><div v-for="p in pending" :key="p.operation_id" class="payment-pending"><div><strong>{{ label(p.kind) }}</strong><div class="mono">{{ p.operation_id }}</div><div class="small-text muted">目标 {{ p.target_id }} · {{ p.created_at }}</div><div v-if="reviews[p.operation_id]?.phase==='submitting'">提交中</div><div v-else-if="reviews[p.operation_id]?.receipt">{{ reviews[p.operation_id]!.receipt!.status==='accepted'?'已接受，等待可靠清理标识':'已明确拒绝，等待可靠清理标识' }}</div><div v-else>结果待核查，不重新提交</div></div><div><el-button :loading="inspectBusy" :disabled="identityBlocked||saving" @click="inspect(p,true)">只读查询原回执</el-button><el-button v-if="['settled','known_failure'].includes(reviews[p.operation_id]?.phase||'')" :disabled="identityBlocked||saving" @click="retryCleanup(p)">重试终态标识清理</el-button></div></div><p class="field-hint">只在本页可见且在线时有限次自动查询。达到次数后保留原编号，可主动只读核查；没有清空后重发按钮。</p></div></section>
  <section v-if="platform&&admin" class="panel payments-section"><div class="panel-header"><div><div class="panel-title">模拟新售开关</div><div class="panel-subtitle">独立配置版本；开启仍受运行环境与系统准入约束。</div></div><el-button @click="loadPolicy">只读刷新配置</el-button></div><div class="panel-body"><template v-if="policy"><p>当前版本 {{ policy.revision }} · {{ policy.effective_enabled?'当前允许新售':'当前未允许新售' }}</p><el-switch v-model="policyEnabled" :disabled="policyStage!=='editing'||identityBlocked" active-text="启用新售" inactive-text="关闭新售" /><el-button :loading="policyStage==='submitting'" :disabled="policyStage!=='editing'||identityBlocked" @click="savePolicy">保存配置</el-button><el-button v-if="policyStage==='unknown'" :disabled="!policyReadReady" @click="newPolicyIntent">基于当前版本重新编辑</el-button></template><p v-else>当前配置尚未可靠读取。</p><p class="field-hint">当前值只表示当前配置，不证明先前未知请求是否生效。重新编辑会开始新的配置意图。</p><el-alert v-if="policyUnknown" title="原配置请求结果未知。上方当前值不证明原请求是否生效；重新编辑表示开始新的配置意图。" type="warning" :closable="false" /></div></section>
  <section class="panel payments-section"><div class="panel-header"><div><div class="panel-title">{{ platform?'模拟充值商品':'可售模拟充值商品' }}</div><div class="panel-subtitle">商品版本不可变，订单保留原价格与收款身份快照。</div></div><el-button v-if="platform&&admin" type="primary" :disabled="!writable" @click="openPublish()">发布新商品</el-button></div>
   <el-table v-if="platform" v-loading="busy.skus" :data="skus" empty-text="暂无模拟商品"><el-table-column label="商品 / 当前版本" min-width="240"><template #default="{row}"><strong>{{ row.current_version?.display_name||'尚无当前版本' }}</strong><div class="small-text mono">{{ row.id }}</div><div class="small-text muted">商品修订 {{ row.revision }} · 版本 {{ row.current_version?.version||'—' }}</div></template></el-table-column><el-table-column label="模拟钱包金额" min-width="170"><template #default="{row}">{{ money(row.current_version?.amount) }}</template></el-table-column><el-table-column label="新售状态" width="110"><template #default="{row}">{{ row.enabled?'启用':'停用' }}</template></el-table-column><el-table-column v-if="admin" label="操作" min-width="230"><template #default="{row}"><el-button :disabled="!writable||blocked('payment.sku.publish',row.id)" @click="openPublish(row)">发布版本</el-button><el-button :disabled="!writable||blocked('payment.sku.activate',row.id)" @click="openActivate(row)">版本与上下架</el-button></template></el-table-column></el-table>
   <div v-else v-loading="busy.skus" class="payments-products"><article v-for="entry in versionRows" :key="entry.version!.id" class="payment-product"><h3>{{ entry.version!.display_name }}</h3><strong>{{ money(entry.version!.amount) }}</strong><p>模拟钱包增加同额余额 · 15 分钟订单窗口</p><p>{{ entry.version!.payee_label }}</p><el-button v-if="owner" type="primary" :disabled="!writable||!capabilities?.payments_enabled||blocked('payment.order.create',entry.version!.id)" @click="perform('payment.order.create',entry.version!.id,{sku_version_id:entry.version!.id})">创建模拟订单</el-button><span v-else class="field-hint">当前为账单只读身份</span></article><p v-if="!sale.length" class="muted">暂无可售模拟商品；读取失败时不会显示为空闲成功状态。</p></div>
   <div class="payments-pagination"><el-button @click="loadList('skus')">第一页</el-button><el-button :disabled="busy.skus||cursor.skus===null" @click="loadList('skus',true)">下一页</el-button></div>
  </section>
  <section class="panel payments-section"><div class="panel-header"><div><div class="panel-title">安全订单</div><div class="panel-subtitle">创建、收银与资金状态独立；HTTP 接受不代表上游已创建或模拟钱包到账。</div></div></div><el-table v-loading="busy.orders" :data="orders" empty-text="暂无订单"><el-table-column label="商品 / 订单" min-width="240"><template #default="{row}"><strong>{{ row.display_name }}</strong><div class="small-text mono">{{ row.id }}</div></template></el-table-column><el-table-column label="模拟金额" min-width="150"><template #default="{row}">{{ money(row.amount) }}</template></el-table-column><el-table-column label="创建 / 收银" min-width="180"><template #default="{row}">{{ label(row.creation_state) }}<div>{{ label(row.checkout_state) }}</div></template></el-table-column><el-table-column label="资金 / 核查" min-width="180"><template #default="{row}">{{ label(row.funding_state) }}<div v-if="row.review_required" class="field-hint">{{ label(row.review_reason) }}</div></template></el-table-column><el-table-column label="查看" min-width="180"><template #default="{row}"><el-button @click="getOrder(row.id)">订单详情</el-button><el-button v-if="!platform&&owner" :disabled="!writable||blocked('payment.order.cancel',row.id)||['closed','cancel_requested'].includes(row.checkout_state)" @click="perform('payment.order.cancel',row.id,{})">申请取消</el-button></template></el-table-column></el-table><div class="payments-pagination"><el-button @click="loadList('orders')">第一页</el-button><el-button :disabled="busy.orders||cursor.orders===null" @click="loadList('orders',true)">下一页</el-button></div></section>
  <section v-if="selected" class="panel payments-section"><div class="panel-header"><div class="panel-title">订单快照</div><el-button @click="getOrder(selected.id)">只读刷新订单</el-button></div><dl class="detail-list panel-body"><dt>订单</dt><dd class="mono">{{ selected.id }}</dd><dt>收款身份</dt><dd>{{ selected.payee_label }} · {{ selected.merchant_id }}</dd><dt>原窗口</dt><dd>{{ selected.created_at }} 至 {{ selected.expires_at }}</dd><dt>安全收银引用</dt><dd class="mono">{{ selected.checkout_ref||'尚无引用' }}</dd><dt>资金</dt><dd>{{ label(selected.funding_state) }}</dd><dt>资金回执 / 日记账</dt><dd class="mono">{{ selected.funding_receipt_id||'—' }} / {{ selected.journal_id||'—' }}</dd><dt>观察时刻</dt><dd>{{ selected.observed_at }}</dd></dl></section>
  <section v-if="platform" class="panel payments-section"><div class="panel-header"><div><div class="panel-title">逻辑订单观察</div><div class="panel-subtitle">可查询尚无订单行的 unknown_order 证据；仅显示安全摘要。</div></div></div><div class="panel-body payments-observation-input"><el-input v-model="logicalOrder" placeholder="规范逻辑订单 UUID" maxlength="36" /><el-button @click="loadList('observations')">只读查询观察</el-button></div><el-table v-loading="busy.observations" :data="observations" empty-text="暂无已验证观察"><el-table-column label="证据 / 处理" min-width="220"><template #default="{row}">{{ label(row.kind) }} · {{ label(row.status) }}<div class="mono small-text">{{ row.id }}</div></template></el-table-column><el-table-column label="固定核查原因" min-width="180"><template #default="{row}">{{ row.reason?label(row.reason):'—' }}</template></el-table-column><el-table-column prop="occurred_at" label="事件时刻" min-width="240" /><el-table-column prop="received_at" label="已验证接收时刻" min-width="240" /></el-table><div class="payments-pagination"><el-button :disabled="!logicalOrder" @click="loadList('observations')">第一页</el-button><el-button :disabled="busy.observations||cursor.observations===null" @click="loadList('observations',true)">下一页</el-button></div></section>
  <el-dialog v-model="publishOpen" title="发布不可变模拟商品版本" width="min(560px, calc(100vw - 28px))" :close-on-click-modal="false"><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><p class="field-hint">本地模拟，无真实收款。基于商品修订 {{ publishForm.revision }} 发布；未知结果只核查原编号。</p><el-form label-position="top" @submit.prevent="publish"><el-form-item label="商品名称"><el-input v-model="publishForm.name" maxlength="100" /></el-form-item><el-form-item label="模拟金额（CNY）"><el-input v-model="publishForm.amount" inputmode="decimal" placeholder="例如 10.000000" maxlength="30" /></el-form-item></el-form><template #footer><el-button @click="publishOpen=false">关闭</el-button><el-button type="primary" :disabled="!writable||blocked('payment.sku.publish',publishForm.sku)" @click="publish">发布版本</el-button></template></el-dialog>
  <el-dialog v-model="activateOpen" title="设置当前版本与新售状态" width="min(560px, calc(100vw - 28px))" :close-on-click-modal="false"><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><p class="field-hint">历史版本编号可从原发布回执取得；归属由服务端核验。切换不改写既有订单。</p><el-form label-position="top" @submit.prevent="activate"><el-form-item label="当前版本 UUID"><el-input v-model="activateForm.version" maxlength="36" /></el-form-item><el-form-item label="新售状态"><el-switch v-model="activateForm.enabled" active-text="启用" inactive-text="停用" /></el-form-item></el-form><template #footer><el-button @click="activateOpen=false">关闭</el-button><el-button type="primary" :disabled="!writable||blocked('payment.sku.activate',activateForm.sku)" @click="activate">保存状态</el-button></template></el-dialog>
